type Campaign = {
  id: string; name: string; description: string | null; locale: string;
  notes: { id: string; title: string; body: string; storyScene: { id: string; title: string } | null; location: { id: string; name: string } | null; quest: { id: string; title: string } | null }[];
  npcs: { id: string; name: string; role: string | null; status: string; description: string | null; personality: string | null; motivation: string | null; voice: string | null; locationId: string | null; factionId: string | null; visibility: string }[];
  locations: { id: string; name: string; description: string | null; readAloud?: string | null; parentId?: string | null }[];
  lore: { id: string; title: string; category: string | null; body: string; visibility: string }[];
  factions: { id: string; name: string; description: string | null; goals: string | null; resources: string | null; allies: string | null; rivals: string | null; reputation: number; visibility: string }[];
  quests: { id: string; title: string; status: string; description: string | null; factionId: string | null }[];
  timeline: { id: string; title: string; description: string | null }[];
  storyScenes: { id: string; title: string; objective: string | null; status: string; sortOrder: number }[];
  combats: { id: string; name: string; status: string; round: number; activeTurnIndex: number; combatants: { id: string; name: string; currentHp: number; maxHp: number; tempHp: number; ac: number; initiative: number; type: string; isActive: boolean; conditions: unknown; monster: { data: unknown } | null; partyMember: { level: number } | null }[] }[];
  maps: { id: string; name: string }[];
};

